 "claims": [
  {
   "claim": "Omar's tablet is at the nightstand at 14:00 on a weekday while he is at work",
   "target": "tablet_omar",
   "expect": "nightstand_b1",
   "days": "weekday",
   "from": 13,
   "to": 15
  },
  {
   "claim": "Omar's controller is at the TV stand at 11:00 on a weekday during his gaming block",
   "target": "controller_omar",
   "expect": "tv_stand_l1",
   "days": "weekday",
   "from": 10,
   "to": 12
  },
  {
   "claim": "Omar's tablet is at the nightstand at 22:00 on a weekday",
   "target": "tablet_omar",
   "expect": "nightstand_b1",
   "days": "weekday",
   "from": 21,
   "to": 23
  }
 ],
 "targets": {
  "tablet_omar": [
   {
    "days": "both",
    "from": 0,
    "to": 24,
    "at": "nightstand_b1",
    "chance": "almost_always"
   },
   {
    "days": "weekday",
    "from": 9.5,
    "to": 11,
    "at": "kitchen_table_k1",
    "chance": "sometimes"
   }
  ],
  "controller_omar": [
   {
